package com.kartyavya.report.controller;
import com.kartyavya.report.dto.ReportDtos.*; import com.kartyavya.report.service.ReportService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportController{private final ReportService s;public ReportController(ReportService s){this.s=s;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)ResponseEntity<ReportResponse> create(@Valid @ModelAttribute CreateRequest r,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return ResponseEntity.status(201).body(s.create(r,a,c));}@GetMapping("/my")List<ReportResponse> mine(Authentication a){return s.mine(a);}@GetMapping("/{id}")ReportResponse one(@PathVariable Long id,Authentication a){return s.one(id,a);}@PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)ReportResponse update(@PathVariable Long id,@Valid @ModelAttribute UpdateRequest r,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return s.update(id,r,a,c);}@DeleteMapping("/{id}")Object delete(@PathVariable Long id,Authentication a){s.delete(id,a);return Map.of("message","Complaint deleted");}@GetMapping("/nearby")List<NearbyReportResponse> nearby(@RequestParam double latitude,@RequestParam double longitude,@RequestParam(defaultValue="1.0")double radiusKm){return s.nearby(latitude,longitude,radiusKm);}@GetMapping("/track/{code}")TrackingResponse track(@PathVariable String code){return s.track(code);}}
